CREATE TABLE "babies" ("id" TEXT NOT NULL, "nickname" TEXT NOT NULL, "birth_date" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NULL, "dirty" INTEGER NOT NULL DEFAULT 0 CHECK ("dirty" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "care_logs" ("id" TEXT NOT NULL, "baby_id" TEXT NOT NULL REFERENCES babies (id), "type" TEXT NOT NULL, "started_at" INTEGER NOT NULL, "ended_at" INTEGER NULL, "detail" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_by" TEXT NULL, "updated_at" INTEGER NULL, "deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("deleted" IN (0, 1)), "dirty" INTEGER NOT NULL DEFAULT 1 CHECK ("dirty" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "cry_events" ("id" TEXT NOT NULL, "baby_id" TEXT NOT NULL REFERENCES babies (id), "started_at" INTEGER NOT NULL, "duration_ms" INTEGER NOT NULL, "audio_path" TEXT NULL, "cry_confidence" REAL NOT NULL DEFAULT 0.0, "context_json" TEXT NOT NULL, "prediction_json" TEXT NOT NULL, "predictor_version" TEXT NOT NULL, "auto_triggered" INTEGER NOT NULL DEFAULT 0 CHECK ("auto_triggered" IN (0, 1)), "sync_state" TEXT NOT NULL DEFAULT 'local', "updated_at" INTEGER NULL, "deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("deleted" IN (0, 1)), "dirty" INTEGER NOT NULL DEFAULT 1 CHECK ("dirty" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "feedbacks" ("id" TEXT NOT NULL, "cry_event_id" TEXT NOT NULL REFERENCES cry_events (id), "resolved_cause" TEXT NOT NULL, "minutes_to_soothe" INTEGER NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "model_versions" ("version" TEXT NOT NULL, "kind" TEXT NOT NULL, "local_path" TEXT NOT NULL, "sha256" TEXT NOT NULL, "active" INTEGER NOT NULL DEFAULT 0 CHECK ("active" IN (0, 1)), "installed_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("version"));
CREATE UNIQUE INDEX care_logs_one_active ON care_logs (baby_id, type) WHERE ended_at IS NULL AND deleted = 0;
